import sys

def solve():
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    a = []
    for i in range(n):
        a.append(int(data[i+1]))

    count = 0
    while True:
        has_divisible = False
        for i in range(n):
            if a[i] % 2 == 0:
                a[i] //= 2
                has_divisible = True
            else:
                a[i] *= 3

        if not has_divisible:
            break
        count += 1

    print(count)

if __name__ == "__main__":
    solve()

